import pandas as pd,numpy as np
from scipy.signal import lfilter
import numpy.linalg as la
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_fault_op1.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv']
D={f:pd.read_csv(f).iloc[::5].reset_index(drop=True) for f in files}
def lag(u,h,tau):
    al=h/tau; return lfilter([al],[1,-(1-al)],u)
def build(sets):
    X=[];Y=[]
    for f in files:
        d=D[f];t=d.time_s.values;V=d.voltage_pu.values;Vs=d.voltage_setpoint_pu.values;th=d.bus_angle_rad.values;P=d.active_power_pu.values
        h=t[1]-t[0]; thd=th-th[0]
        om=(thd-lag(thd,h,0.1))/0.1/(2*np.pi*60)
        Q=d.reactive_power_pu.values
        cols=[]
        for name in sets:
            if name=='e_int': cols.append(lag(Vs-V,h,0.2))
            if name=='e': cols.append(Vs-V)
            if name=='V': cols.append(V-V[0])
            if name=='Vlag': cols.append(lag(V-V[0],h,0.05))
            if name=='P': cols.append(P-P[0])
            if name=='om': cols.append(om)
            if name=='one': cols.append(np.ones(len(V))*0)
        X.append(np.column_stack(cols));Y.append(Q-Q[0])
    return np.vstack(X),np.concatenate(Y)
for sets in [['e','V'],['e','V','P'],['e','V','om'],['e','V','P','om'],['e_int','Vlag','P','om'],['e','V','Vlag','P','om'],['e','e_int','V','P','om']]:
    X,Y=build(sets); c=la.lstsq(X,Y,rcond=None)[0]
    print(sets, np.round(c,3), 'rms',round(np.sqrt(np.mean((Y-X@c)**2)),5))

